<?php
namespace Tapin\ServicePointLocator\PriceCheck;
use Tapin\ServicePointLocator\PriceCheck\PythonValue as V;
defined( 'ABSPATH' ) || exit;

/** Source XLSX imports are previews only; persistence remains the explicit provider/shop save. */
final class WorkbookApiService {
	const OPERATIONS = array( 'admin_shops_sample', 'admin_import_shops', 'admin_locations_sample', 'admin_locations_import' );
	private $read;
	public function __construct( ?callable $read = null ) { $this->read = $read ?? array( PriceWorkbook::class, 'read' ); }
	private static function name( $text ): string { return str_replace( '‌', '', ProviderSchema::fold( preg_replace( '/[\s\x{001c}-\x{001f}]+/u', '', V::string( V::fallback( $text, '' ) ) ) ) ); }
	private static function cell( $value ): string { return null === $value || is_bool( $value ) ? '' : V::text( $value ); }
	public function preview( string $kind, array $book ): array {
		$rows = $errors = $provinces = $cities = $seen_p = $seen_c = array();
		if ( 'shops' === $kind ) { foreach ( $book['sheets'][$book['active']]['rows'] as $index => $row ) { $cells = array_map( static fn( $v ) => null === $v ? null : V::trim( V::string( $v ) ), $row ); if ( ! array_filter( $cells, array( V::class, 'truth' ) ) ) { continue; } if ( 0 === $index && in_array( ProviderSchema::fold( $cells[0] ?? '' ), array( 'id', 'shop_id', 'شناسه', 'شناسه شعبه' ), true ) ) { continue; } $raw = array(); foreach ( array( 'id', 'title', 'province', 'city', 'token' ) as $i => $column ) { $raw[$column] = $cells[$i] ?? ''; } try { $rows[] = ShopStorage::clean_row( (object) $raw ); } catch ( \InvalidArgumentException $error ) { $errors[] = array( 'field' => 'row ' . ( $index + 1 ), 'message' => $error->getMessage() ); } } return array( 'rows' => $rows, 'errors' => $errors, 'valid' => count( $rows ) ); }
		$targets = array(); foreach ( $book['sheets'] as $sheet ) { $name = self::name( $sheet['title'] ); if ( in_array( $name, array( 'provinces', 'province', 'استان', 'استانها', 'ostan' ), true ) ) { $targets[] = array( 'provinces', $sheet['rows'] ); } elseif ( in_array( $name, array( 'cities', 'city', 'شهر', 'شهرها', 'shahr' ), true ) ) { $targets[] = array( 'cities', $sheet['rows'] ); } }
		if ( ! $targets && 1 === count( $book['sheets'] ) ) { $widest = 0; foreach ( $book['sheets'][0]['rows'] as $row ) { $widest = max( $widest, count( array_filter( array_map( array( self::class, 'cell' ), $row ), array( V::class, 'truth' ) ) ) ); if ( $widest >= 3 ) { break; } } $targets[] = array( $widest >= 3 ? 'cities' : 'provinces', $book['sheets'][0]['rows'] ); }
		if ( ! $targets ) { throw new QuoteError( 422, 'شیت استان (provinces) یا شهر (cities) در فایل پیدا نشد.' ); }
		foreach ( $targets as [$type, $values] ) { $header = false; foreach ( $values as $index => $row ) { $cells = array_map( array( self::class, 'cell' ), $row ); if ( ! array_filter( $cells, array( V::class, 'truth' ) ) ) { continue; } if ( ! $header ) { $header = true; $words = array( 'code', 'کد', 'کداستان', 'کدشهر', 'title', 'label', 'عنوان', 'نام', 'province', 'provincecode', 'city', 'citycode' ); if ( array_intersect( array_map( array( self::class, 'name' ), array_slice( $cells, 0, 3 ) ), $words ) ) { continue; } } $label = $type . ' row ' . ( $index + 1 ); $code = $cells[0] ?? ''; $title = $cells[1] ?? ''; $province = $cells[2] ?? ''; $is_p = 'provinces' === $type; $noun = $is_p ? 'استان' : 'شهر'; $seen = $is_p ? $seen_p : $seen_c; $message = '';
			if ( '' === $code ) { $message = 'کد ' . $noun . ' خالی است.'; } elseif ( V::length( $code ) > 30 ) { $message = 'کد ' . $noun . ' بیش از حد طولانی است.'; } elseif ( in_array( $code, $seen, true ) ) { $message = 'کد ' . $noun . ' تکراری: ' . $code; } elseif ( ! $is_p && '' === $province ) { $message = 'کد استان شهر الزامی است.'; } if ( '' !== $message ) { $errors[] = array( 'field' => $label, 'message' => $message ); continue; }
			if ( $is_p ) { $seen_p[] = $code; $provinces[] = array( 'code' => $code, 'title' => V::fallback( $title, $code ) ); } else { $seen_c[] = $code; $cities[] = array( 'code' => $code, 'title' => V::fallback( $title, $code ), 'province_code' => $province ); }
		} } if ( count( $provinces ) > 500 ) { $errors[] = array( 'field' => 'provinces', 'message' => 'حداکثر 500 استان.' ); $provinces = array_slice( $provinces, 0, 500 ); } if ( count( $cities ) > 20000 ) { $errors[] = array( 'field' => 'cities', 'message' => 'حداکثر 20000 شهر.' ); $cities = array_slice( $cities, 0, 20000 ); } return array( 'provinces' => $provinces, 'cities' => $cities, 'errors' => $errors, 'valid' => count( $provinces ) + count( $cities ) );
	}
	public function call( string $operation, RestInput $input ): RestResult {
		$shop = in_array( $operation, array( 'admin_shops_sample', 'admin_import_shops' ), true );
		if ( in_array( $operation, array( 'admin_shops_sample', 'admin_locations_sample' ), true ) ) { $sheets = $shop ? array( array( 'title' => 'shops', 'rows' => array( array( 'id', 'title', 'province', 'city', 'token' ), array( '101', 'شعبه مرکزی', '1', '1', 'TOKEN' ), array( '102', 'شعبه کرج', '2', '30', 'TOKEN' ) ) ) ) : array( array( 'title' => 'provinces', 'rows' => array( array( 'code', 'title' ), array( '1', 'تهران' ), array( '2', 'اصفهان' ) ) ), array( 'title' => 'cities', 'rows' => array( array( 'code', 'title', 'province_code' ), array( '10', 'تهران', '1' ), array( '20', 'اصفهان', '2' ) ) ) ); return new RestResult( null, 200, array( 'Content-Type' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'Content-Disposition' => 'attachment; filename="' . ( $shop ? 'shops' : 'locations' ) . '-sample.xlsx"' ), PriceWorkbook::write( $sheets ) ); }
		$file = $input->files['file'] ?? null; if ( ! is_array( $file ) || empty( $file['tmp_name'] ) || ( $file['error'] ?? 0 ) ) { throw new QuoteError( 400, 'فایل اکسل ارسال نشده است.' ); } clearstatcache( true, $file['tmp_name'] ); $size = @filesize( $file['tmp_name'] ); if ( false === $size ) { throw new QuoteError( 422, 'فایل اکسل خوانده نشد.' ); } if ( 0 === $size ) { throw new QuoteError( 400, 'فایل خالی است.' ); } if ( $size > 5 * 1024 * 1024 ) { throw new QuoteError( 413, 'حجم فایل نباید بیشتر از 5 مگابایت باشد.' ); }
		try { $book = ( $this->read )( $file['tmp_name'], $shop ); } catch ( \Throwable $error ) { throw new QuoteError( 422, 'فایل اکسل خوانده نشد.' ); } return new RestResult( $this->preview( $shop ? 'shops' : 'locations', $book ) );
	}
}
